-- Tableros de Umami. Se crean una vez; luego se pueden editar en el panel (no se pisan).
-- Panel principal (Dashboard) del usuario admin: resumen de todas las webs.
INSERT INTO board (board_id, type, name, description, parameters, user_id)
SELECT u.user_id, 'dashboard', 'Grupo · resumen', 'Todas las webs del grupo', '{"rows": [{"id": "r1", "columns": [{"id": "c2", "component": {"type": "TextBlock", "props": {"text": "Visitas de todas las webs del grupo. Cada web tiene su tablero con el detalle en Boards. Sin cookies: no cuenta a quien bloquea scripts."}}}]}, {"id": "r3", "columns": [{"id": "c4", "component": {"type": "WebsiteMetricsBar", "websiteId": "a3a6b5ee-66b7-4893-a295-2e6e9fe188b4", "entityType": "website", "entityId": "a3a6b5ee-66b7-4893-a295-2e6e9fe188b4", "title": "JomaPaint"}}, {"id": "c5", "component": {"type": "WebsiteMetricsBar", "websiteId": "72937a60-e911-4d1e-bf34-4e358686f870", "entityType": "website", "entityId": "72937a60-e911-4d1e-bf34-4e358686f870", "title": "Joma Urban"}}]}, {"id": "r6", "columns": [{"id": "c7", "component": {"type": "WebsiteMetricsBar", "websiteId": "7d999b89-c4ff-4e67-83cc-b6f5cd541703", "entityType": "website", "entityId": "7d999b89-c4ff-4e67-83cc-b6f5cd541703", "title": "Normo"}}, {"id": "c8", "component": {"type": "WebsiteMetricsBar", "websiteId": "f9227910-44f9-4cc7-9834-24ef6ec1fb9b", "entityType": "website", "entityId": "f9227910-44f9-4cc7-9834-24ef6ec1fb9b", "title": "Ekilabs"}}]}, {"id": "r9", "columns": [{"id": "c10", "component": {"type": "WebsiteMetricsBar", "websiteId": "86cc56b6-fb47-4115-87a9-3eda024bf97d", "entityType": "website", "entityId": "86cc56b6-fb47-4115-87a9-3eda024bf97d", "title": "Joma"}}, {"id": "c11", "component": {"type": "WebsiteMetricsBar", "websiteId": "1272970f-f4e1-4967-9c29-0de23b16aee3", "entityType": "website", "entityId": "1272970f-f4e1-4967-9c29-0de23b16aee3", "title": "Joma Urban (staging, pruebas)"}}]}, {"id": "r12", "columns": [{"id": "c13", "component": {"type": "WebsiteChart", "websiteId": "a3a6b5ee-66b7-4893-a295-2e6e9fe188b4", "entityType": "website", "entityId": "a3a6b5ee-66b7-4893-a295-2e6e9fe188b4", "title": "JomaPaint · visitas"}}, {"id": "c14", "component": {"type": "WebsiteChart", "websiteId": "72937a60-e911-4d1e-bf34-4e358686f870", "entityType": "website", "entityId": "72937a60-e911-4d1e-bf34-4e358686f870", "title": "Joma Urban · visitas"}}]}, {"id": "r15", "columns": [{"id": "c16", "component": {"type": "MetricsTable", "websiteId": "a3a6b5ee-66b7-4893-a295-2e6e9fe188b4", "entityType": "website", "entityId": "a3a6b5ee-66b7-4893-a295-2e6e9fe188b4", "title": "JomaPaint · acciones", "description": "Solicitudes enviadas, clics en teléfono y email", "props": {"type": "event", "limit": 10}}}, {"id": "c17", "component": {"type": "MetricsTable", "websiteId": "72937a60-e911-4d1e-bf34-4e358686f870", "entityType": "website", "entityId": "72937a60-e911-4d1e-bf34-4e358686f870", "title": "Joma Urban · acciones", "description": "Solicitudes, teléfono, email, WhatsApp y descargas", "props": {"type": "event", "limit": 10}}}]}]}'::jsonb, u.user_id
